from rdkit import Chem
from itertools import product

base = Chem.MolFromSmiles("CC1CCC2C(C)C3CC(O)C(C)C3CN2C1")
centers = [1, 4, 5, 7, 9, 11, 13]
desired = {1:'S', 4:'R', 5:'S', 7:'R', 9:'S', 11:'S', 13:'R'}

found = []
for combo in product([Chem.ChiralType.CHI_TETRAHEDRAL_CW, Chem.ChiralType.CHI_TETRAHEDRAL_CCW], repeat=7):
    m = Chem.Mol(base)
    for idx, tag in zip(centers, combo):
        m.GetAtomWithIdx(idx).SetChiralTag(tag)
    Chem.AssignStereochemistry(m, cleanIt=True, force=True)
    labels = {}
    ok = True
    for idx in centers:
        a = m.GetAtomWithIdx(idx)
        if not a.hasProp('_CIPCode'):
            ok = False; break
        labels[idx] = a.GetProp('_CIPCode')
    if ok and all(labels[k] == desired[k] for k in desired):
        found.append(Chem.MolToSmiles(m, isomericSmiles=True))

print("Number of matching stereoisomers:", len(found))
for s in found[:5]:
    print(s)
EOF
python3 stereo.py
